pseudocode.part3:
semaphore mutex = 1;
P1: wait(mutex); C3; signal(mutex);
P2: wait(mutex); C3; signal(mutex);

pseudocode.P1:
while (true) {
  x=produce();
  wait(empty);
  wait(mutex);
  put(); //放入本次生成的x，保留题设函数名
  signal(mutex);
  if (x%2==1) signal(odd); else signal(even);
}

pseudocode.P2:
while (true) {
  wait(odd);
  wait(mutex);
  getodd();
  signal(mutex);
  signal(empty);
  countodd();
}

pseudocode.P3:
while (true) {
  wait(even);
  wait(mutex);
  geteven();
  signal(mutex);
  signal(empty);
  counteven();
}

pseudocode.initial:
semaphore empty=1000, full=0, mutex=1, batch=1;
int in=0, out=0;
item buf[1000];

pseudocode.producer:
while (true) {
  x=produce();
  wait(empty);
  wait(mutex);
  buf[in]=x; in=(in+1)%1000;
  signal(mutex);
  signal(full);
}

pseudocode.consumer:
item local[10]; //每个消费者的私有数组
while (true) {
  wait(batch);
  for (int k=0; k<10; ++k) {
    wait(full);
    wait(mutex);
    local[k]=buf[out]; out=(out+1)%1000;
    signal(mutex);
    signal(empty);
  }
  signal(batch);
  consume(local);
}

